  "nl": "Hartlelie, funkia",
  "speciaal": "Ongeveer 45 soorten, vooral uit Japan, en daarnaast enkele uit China, Korea en Rusland. Vooral gekweekt om het blad; er bestaan zeer veel cultivars en synoniemen, wat het benoemen moeilijk maakt.",
